/**
 * Monday.com Node - Version 2
 * Discriminator: resource=item, operation=createItem
 */


// Helper types for special n8n fields
type ResourceMapperField = { id?: string; displayName?: string; required?: boolean; defaultMatch?: boolean; display?: boolean; type?: string; canBeUsedToMatch?: boolean; [key: string]: unknown };
type ResourceMapperCommon = { matchingColumns?: string[]; cachedResultName?: string; [key: string]: unknown };
type ResourceMapperValue = ResourceMapperCommon & { mappingMode: string; value?: null | Record<string, unknown>; schema?: ResourceMapperField[] };

interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Create a new item on a board — or a subitem under a parent item — with column values */
export type MondayComV2ItemCreateItemParams = {
  resource: 'item';
  operation: 'createItem';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The board to operate on
 * @searchListMethod searchBoards
 * @default {"mode":"list","value":""}
 */
    boardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to create a top-level item or a subitem under a parent item
 * @default item
 */
    createAs?: 'subitem' | 'item';
/**
 * The item to create the subitem under. On classic boards subitems get the subitem board's own columns; on multi-level boards all levels share the parent board's columns and the parent can be a subitem itself (up to 5 levels).
 * @searchListMethod searchItems
 * @displayOptions.show { createAs: ["subitem"] }
 * @default {"mode":"list","value":""}
 */
    itemId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The name of the new item
 */
    name: string | Expression<string>;
/**
 * Column Values
 * @default mapper
 */
    columnValuesMode?: 'mapper' | 'json';
/**
 * Columns
 * @displayOptions.show { columnValuesMode: ["mapper"] }
 * @default {"mappingMode":"defineBelow","value":null}
 */
    columns?: ResourceMapperValue;
/**
 * Column values in the monday API format, keyed by column ID (e.g. {"status": {"label": "Done"}}). See &lt;a href="https://developer.monday.com/api-reference/reference/column-types-reference"&gt;the column types reference&lt;/a&gt;.
 * @displayOptions.show { columnValuesMode: ["json"] }
 * @default {}
 */
    columnValuesJson?: IDataObject | string | Expression<string>;
/**
 * Options
 * @default {}
 */
    createOptions?: {
    /** The group to create the item in; defaults to the board's top group. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getBoardGroups
     * @displayOptions.hide { /createAs: ["subitem"] }
     */
    groupId?: string | Expression<string>;
    /** Whether to create status/dropdown labels that do not exist yet (requires board owner permissions)
     * @default false
     */
    createLabelsIfMissing?: boolean | Expression<boolean>;
  };
};

export type MondayComV2ItemCreateItemNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2ItemCreateItemParams> & { credentials?: Credentials };
};